#!/usr/bin/python
import sys


def parse_counter(text, line_number):
    digits = text.strip()
    if not digits:
        raise ValueError("invalid counter on line %d" % line_number)

    value = 0
    for digit in digits:
        if digit < '0' or digit > '9':
            raise ValueError("invalid counter on line %d" % line_number)
        value = value * 10 + (ord(digit) - ord('0'))
    return value


def main():
    total = 0
    with open(sys.argv[1]) as counters:
        for line_number, line in enumerate(counters, 1):
            try:
                total += parse_counter(line, line_number)
            except ValueError as error:
                sys.stderr.write(str(error) + "\n")
                return 1

    sys.stdout.write(str(total) + "\n")
    return 0


if __name__ == '__main__':
